-- Seed: Indian species catalogue extension (BR-PLT-01). Plants commonly grown
-- in Indian homes, balconies and gardens — sacred, medicinal, flowering, fruit
-- and kitchen-garden species. Same reference conditions as 001: base interval
-- assumes BRIGHT_INDIRECT light, ceramic-glazed pot, standard potting soil.
-- Stable ids (a0…0011 onward) so a re-seed upserts rather than duplicating.

begin;

  -- Batch 2 — flowering shrubs, sacred trees, ayurvedic herbs, kitchen garden.
  ('a0000000-0000-4000-8000-000000000041', 'Nerium oleander',           'Kaner (Oleander)',          6,  4, 14, 'DIRECT_SUN',      'GARDEN_SOIL',      'Tough highway shrub, blooms through heat. Every part is poisonous — wash hands.'),
  ('a0000000-0000-4000-8000-000000000042', 'Cestrum nocturnum',         'Raat ki Rani',              3,  2,  7, 'BRIGHT_INDIRECT', 'STANDARD_POTTING', 'Night-blooming jessamine; one plant scents a whole street after dusk.'),
  ('a0000000-0000-4000-8000-000000000043', 'Combretum indicum',         'Madhumalti',                4,  2,  8, 'DIRECT_SUN',      'GARDEN_SOIL',      'Rangoon creeper — flowers open white, blush pink, then crimson on the same vine.'),
  ('a0000000-0000-4000-8000-000000000044', 'Tecoma stans',              'Yellow Bells (Piliya)',     5,  3, 10, 'DIRECT_SUN',      'GARDEN_SOIL',      'Trumpet flowers most of the year. Forgives missed waterings.'),
  ('a0000000-0000-4000-8000-000000000045', 'Cassia fistula',            'Amaltas',                   8,  5, 18, 'DIRECT_SUN',      'GARDEN_SOIL',      'Golden shower tree of May. Slow to start, indestructible after.'),
  ('a0000000-0000-4000-8000-000000000046', 'Bauhinia variegata',        'Kachnar',                   6,  4, 14, 'DIRECT_SUN',      'GARDEN_SOIL',      'Orchid-like blooms; the buds are the sabzi. Light water once established.'),
  ('a0000000-0000-4000-8000-000000000047', 'Withania somnifera',        'Ashwagandha',               7,  4, 15, 'DIRECT_SUN',      'CACTUS_SUCCULENT', 'Ayurvedic root herb for dry climates. Overwatering is its only enemy.'),
  ('a0000000-0000-4000-8000-000000000048', 'Bacopa monnieri',           'Brahmi',                    2,  1,  4, 'MEDIUM',          'PEAT_BASED',       'Memory herb that loves wet feet — happy even in a shallow water tray.'),
  ('a0000000-0000-4000-8000-000000000049', 'Centella asiatica',         'Mandukaparni (Gotu Kola)',  2,  1,  4, 'MEDIUM',          'PEAT_BASED',       'Creeping ayurvedic green for chutneys. Keep consistently moist, part shade.'),
  ('a0000000-0000-4000-8000-00000000004a', 'Santalum album',            'Chandan (Sandalwood)',      7,  4, 16, 'DIRECT_SUN',      'GARDEN_SOIL',      'Semi-parasitic — plant near a host like Tulsi or pigeon pea to thrive.'),
  ('a0000000-0000-4000-8000-00000000004b', 'Saraca asoca',              'Sita Ashok',                5,  3, 10, 'BRIGHT_INDIRECT', 'GARDEN_SOIL',      'The true Ashok of temple courtyards; orange-red bloom clusters in spring.'),
  ('a0000000-0000-4000-8000-00000000004c', 'Magnolia champaca',         'Son Champa',                4,  3,  9, 'DIRECT_SUN',      'GARDEN_SOIL',      'The champa of garlands and attar. Deep watering, hates root disturbance.'),
  ('a0000000-0000-4000-8000-00000000004d', 'Mimusops elengi',           'Bakul (Maulsari)',          6,  4, 13, 'DIRECT_SUN',      'GARDEN_SOIL',      'Small evergreen with tiny star flowers that keep their scent even dried.'),
  ('a0000000-0000-4000-8000-00000000004e', 'Butea monosperma',          'Palash (Flame of Forest)',  8,  5, 18, 'DIRECT_SUN',      'GARDEN_SOIL',      'Holi''s orange dye tree. Drought-hardy; young plants need staking.'),
  ('a0000000-0000-4000-8000-00000000004f', 'Nelumbo nucifera',          'Kamal (Lotus)',             1,  1,  2, 'DIRECT_SUN',      'OTHER',            'National flower; grows in a water tub, not soil-watering — top up daily.'),
  ('a0000000-0000-4000-8000-000000000050', 'Tabernaemontana divaricata','Chandni (Crepe Jasmine)',   3,  2,  7, 'BRIGHT_INDIRECT', 'STANDARD_POTTING', 'Pinwheel white flowers on glossy green. Steady moisture, no hard sun at noon.'),
  ('a0000000-0000-4000-8000-000000000051', 'Gardenia jasminoides',      'Gandhraj',                  3,  2,  6, 'BRIGHT_INDIRECT', 'PEAT_BASED',       'Heady fragrance, fussy roots: acidic soil, soft water, no cold draughts.'),
  ('a0000000-0000-4000-8000-000000000052', 'Portulaca grandiflora',     'Nau Baje (Table Rose)',     4,  2,  9, 'DIRECT_SUN',      'CACTUS_SUCCULENT', 'Opens at nine, closes by dusk. Succulent leaves — water sparingly.'),
  ('a0000000-0000-4000-8000-000000000053', 'Zinnia elegans',            'Zinnia',                    3,  2,  6, 'DIRECT_SUN',      'GARDEN_SOIL',      'Cut-and-come-again summer annual. Water the soil, not the leaves.'),
  ('a0000000-0000-4000-8000-000000000054', 'Celosia cristata',          'Lal Murga (Cockscomb)',     3,  2,  6, 'DIRECT_SUN',      'GARDEN_SOIL',      'Velvet comb flowers in monsoon beds. Even moisture, good drainage.'),
  ('a0000000-0000-4000-8000-000000000055', 'Gomphrena globosa',         'Vadamalli (Globe Amaranth)',4,  2,  8, 'DIRECT_SUN',      'GARDEN_SOIL',      'Papery purple buttons for kolam-side pots and garlands; nearly carefree.'),
  ('a0000000-0000-4000-8000-000000000056', 'Chrysanthemum morifolium',  'Shevanti (Guldaudi)',       3,  2,  6, 'DIRECT_SUN',      'STANDARD_POTTING', 'Winter show-flower of Indian terraces. Pinch tips until October for bushiness.'),
  ('a0000000-0000-4000-8000-000000000057', 'Dahlia pinnata',            'Dahlia',                    3,  2,  6, 'DIRECT_SUN',      'GARDEN_SOIL',      'Tubers give dinner-plate blooms in winter. Stake early, water deeply.'),
  ('a0000000-0000-4000-8000-000000000058', 'Canna indica',              'Keli (Canna Lily)',         3,  2,  6, 'DIRECT_SUN',      'GARDEN_SOIL',      'Bold monsoon banana-leaf look-alike. Thirsty in bloom; cut spent stalks.'),
  ('a0000000-0000-4000-8000-000000000059', 'Lagenaria siceraria',       'Lauki (Bottle Gourd)',      2,  1,  4, 'DIRECT_SUN',      'GARDEN_SOIL',      'Terrace-net climber; hand-pollinate evening flowers for more fruit.'),
  ('a0000000-0000-4000-8000-00000000005a', 'Abelmoschus esculentus',    'Bhindi (Okra)',             2,  1,  4, 'DIRECT_SUN',      'GARDEN_SOIL',      'Pick pods young every two days or they turn woody. Loves heat.'),
  ('a0000000-0000-4000-8000-00000000005b', 'Solanum melongena',         'Baingan (Brinjal)',         2,  1,  4, 'DIRECT_SUN',      'GARDEN_SOIL',      'Heavy feeder. Even watering prevents bitter, seedy fruit.'),
  ('a0000000-0000-4000-8000-00000000005c', 'Momordica charantia',       'Karela (Bitter Gourd)',     2,  1,  4, 'DIRECT_SUN',      'GARDEN_SOIL',      'Vigorous net climber; yellow flowers, spiny fruit. Steady water, rich soil.'),
  ('a0000000-0000-4000-8000-00000000005d', 'Ficus microcarpa',          'Chinese Banyan (bonsai)',   5,  3, 10, 'BRIGHT_INDIRECT', 'STANDARD_POTTING', 'The classic beginner bonsai ficus. Aerial roots love humidity.'),
  ('a0000000-0000-4000-8000-00000000005e', 'Ocimum tenuiflorum ''Krishna''', 'Krishna Tulsi',        2,  1,  5, 'DIRECT_SUN',      'STANDARD_POTTING', 'Purple-leaved tulsi, stronger aroma than Rama tulsi. Same sun-and-water rhythm.')
